const items = $input.all().map(i => i.json);
let events = items;
if (items.length === 1 && Array.isArray(items[0].body)) { events = items[0].body; }
const ids = [];
for (const e of events) {
  if (!e) { continue; }
  if (e.subscriptionType && e.subscriptionType !== 'contact.propertyChange') { continue; }
  if (e.propertyName && e.propertyName !== 'agente') { continue; }
  const rawId = e.contactId ?? e.objectId;
  if (!rawId) { continue; }
  const id = String(rawId);
  if (!ids.includes(id)) { ids.push(id); }
}
if (!ids.length) { return []; }
return [{ json: { batchBody: { properties: ['agente', 'conversation_transcript_url', 'firstname', 'phone', 'whatsapp_id'], inputs: ids.map(id => ({ id: id })) } } }];

const AGENT_IDS = { 'Ana Gomez': 3, 'Beatriz Ruiz': 4, 'Carolina Diaz': 6, 'Diana Mejia': 7 };
const results = $input.first().json.results ?? [];
const out = [];
for (const c of results) {
  const p = c.properties ?? {};
  const agente = p.agente;
  const assigneeId = AGENT_IDS[agente];
  if (!assigneeId) { continue; }
  const url = String(p.conversation_transcript_url ?? '');
  const parts = url.split('/conversations/');
  if (parts.length < 2) { continue; }
  const conversationId = parseInt(parts[1], 10);
  if (!conversationId) { continue; }
  const accParts = parts[0].split('/accounts/');
  const accountId = accParts.length > 1 ? parseInt(accParts[1], 10) : 1;
  out.push({ json: { contact_id: c.id, firstname: p.firstname ?? null, agente: agente, assignee_id: assigneeId, account_id: accountId, conversation_id: conversationId } });
}
return out;

const desired = $('Preparar asignaciones').all();
const convs = $input.all();
const out = [];
for (let i = 0; i < convs.length; i++) {
  const d = desired[i] ? desired[i].json : null;
  const c = convs[i] ? convs[i].json : null;
  if (!d || !c || !c.id) { continue; }
  const current = c.meta?.assignee?.id ?? null;
  if (current === d.assignee_id) { continue; }
  out.push({ json: { contact_id: d.contact_id, agente: d.agente, assignee_id: d.assignee_id, account_id: d.account_id, conversation_id: d.conversation_id, assignee_actual: current } });
}
return out;

const AGENTES = ['Ana Gomez', 'Beatriz Ruiz', 'Carolina Diaz', 'Diana Mejia'];
const FASE_CERRADA = '4';
const results = $input.first().json.results ?? [];
const out = [];
const vistos = [];
for (const c of results) {
  const agente = c.properties?.agente;
  if (!AGENTES.includes(agente)) { continue; }
  const contactId = String(c.id);
  if (vistos.includes(contactId)) { continue; }
  vistos.push(contactId);
  out.push({ json: { contact_id: contactId, agente: agente, searchBody: { filterGroups: [{ filters: [{ propertyName: 'associations.contact', operator: 'EQ', value: contactId }, { propertyName: 'hs_pipeline_stage', operator: 'NEQ', value: FASE_CERRADA }] }], properties: ['agente', 'subject', 'hs_pipeline_stage'], limit: 100 } } });
}
return out;

const origen = $('Preparar tickets del contacto').all();
const respuestas = $input.all();
const out = [];
for (let i = 0; i < respuestas.length; i++) {
  const src = origen[i] ? origen[i].json : null;
  if (!src) { continue; }
  const tickets = respuestas[i]?.json?.results ?? [];
  for (const t of tickets) {
    const actual = t.properties?.agente ?? null;
    if (actual === src.agente) { continue; }
    out.push({ json: { ticket_id: String(t.id), agente: src.agente, agente_anterior: actual, contact_id: src.contact_id, subject: t.properties?.subject ?? null } });
  }
}
return out;

const items = $input.all().map(i => i.json);
let events = items;
if (items.length === 1 && Array.isArray(items[0].body)) { events = items[0].body; }
const ids = [];
for (const e of events) {
  if (!e) { continue; }
  if (e.subscriptionType !== 'ticket.propertyChange') { continue; }
  if (e.propertyName && e.propertyName !== 'agente') { continue; }
  const rawId = e.objectId ?? e.ticketId ?? e.contactId;
  if (!rawId) { continue; }
  const id = String(rawId);
  if (!ids.includes(id)) { ids.push(id); }
}
return ids.map(id => ({ json: { ticket_id: id } }));

const AGENTES = ['Ana Gomez', 'Beatriz Ruiz', 'Carolina Diaz', 'Diana Mejia'];
const out = [];
for (const item of $input.all()) {
  const t = item.json ?? {};
  if (!t.id) { continue; }
  const agente = t.properties?.agente;
  if (!AGENTES.includes(agente)) { continue; }
  const contactos = t.associations?.contacts?.results ?? [];
  const contactId = contactos[0]?.id ?? null;
  if (!contactId) { continue; }
  out.push({ json: { contact_id: String(contactId), agente: agente, ticket_id: String(t.id) } });
}
return out;

const results = $input.first().json.results ?? [];
const ids = results.map(t => String(t.id));
if (!ids.length) { return []; }
return [{ json: { batchBody: { properties: ['agente'], propertiesWithHistory: ['agente'], inputs: ids.map(id => ({ id: id })) } } }];

const AGENTES = ['Ana Gomez', 'Beatriz Ruiz', 'Carolina Diaz', 'Diana Mejia'];
const APP_PROPIA = '<SERVICE_KEY_APP_ID>';
const VENTANA_MIN = 20;
const corte = Date.now() - VENTANA_MIN * 60 * 1000;
const results = $input.first().json.results ?? [];
const out = [];
for (const t of results) {
  const ultimo = (t.propertiesWithHistory?.agente ?? [])[0];
  if (!ultimo) { continue; }
  if (String(ultimo.sourceId ?? '') === APP_PROPIA) { continue; }
  if (new Date(ultimo.timestamp).getTime() < corte) { continue; }
  if (!AGENTES.includes(ultimo.value)) { continue; }
  out.push({ json: { ticket_id: String(t.id), agente: ultimo.value, cambiado_en: ultimo.timestamp, origen: ultimo.sourceType } });
}
return out;

const ids = [];
for (const item of $input.all()) {
  const rawId = item.json?.id;
  if (!rawId) { continue; }
  const id = String(rawId);
  if (!ids.includes(id)) { ids.push(id); }
}
if (!ids.length) { return []; }
return [{ json: { batchBody: { properties: ['agente', 'conversation_transcript_url', 'firstname', 'phone', 'whatsapp_id'], inputs: ids.map(id => ({ id: id })) } } }];
